// The browser version with real sound: the library, playlists and suggestions come from the
// demo backend, while decks, the mixer, FX, the sampler and recording run on the Rust
// engine compiled to WebAssembly (see ../web/engine.ts). Library tracks are generated by
// mixit-generator at their listed style, tempo and key, and the person can add their own
// audio files, which are decoded and analysed in the browser.

import { DemoBackend, DEMO_KIT, emptyPad, kitPad, type DemoTrack } from "./demo";
import type * as T from "./types";
import { concat, encodeWav, parseWave, RenderCancelled, toPcm16, trimSilence, wavHeader, WebEngine, type AnalysisView, type GenerateRequest, type GridView, type RenderNeed, type RenderTrack } from "../web/engine";

const AUDIO = ["wav", "mp3", "flac", "aiff", "aif", "ogg", "m4a", "aac", "opus", "webm"];
/** Ids for tracks the person adds (the generated library uses 1..120, practice 1001+). */
const FIRST_FILE_ID = 5_001;

interface Analysed {
  view: AnalysisView;
  wave: Uint8Array;
}

/** The generator style closest to a library genre. */
export function styleForGenre(genre: string): string {
  const g = genre.toLowerCase();
  if (g.includes("drum") || g.includes("dnb") || g.includes("jungle")) return "dnb";
  if (g.includes("hip") || g.includes("rap") || g.includes("trap")) return "hiphop";
  if (g.includes("trance")) return "trance";
  if (g.includes("techno")) return "techno";
  return "house";
}

/** "Practice 3 - Night Techno" → "p3". */
export function practiceId(title: string): string | null {
  const m = /^Practice (\d+) - /.exec(title);
  return m ? `p${m[1]}` : null;
}

/** Opens the browser's file picker. Resolves with nothing when the person cancels. */
function pick(opts: { accept?: string[]; multiple?: boolean; folder?: boolean }): Promise<File[]> {
  return new Promise((resolve) => {
    const input = document.createElement("input");
    input.type = "file";
    input.multiple = !!opts.multiple;
    if (opts.folder) input.setAttribute("webkitdirectory", "");
    if (opts.accept) input.accept = opts.accept.map((e) => `.${e}`).join(",");
    input.style.display = "none";
    let done = false;
    const finish = (files: File[]) => {
      if (done) return;
      done = true;
      input.remove();
      resolve(files);
    };
    input.addEventListener("change", () => finish([...(input.files ?? [])]));
    input.addEventListener("cancel", () => finish([]));
    document.body.appendChild(input);
    input.click();
  });
}

function download(blob: Blob, name: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 60_000);
}

const ext = (name: string) => name.split(".").pop()?.toLowerCase() ?? "";
const stem = (name: string) => name.split(/[\\/]/).pop()!.replace(/\.[^.]+$/, "");

export class WebAudioBackend extends DemoBackend {
  readonly kind = "web" as const;
  private analysed = new Map<number, Analysed>();
  /** Files the person picked, under the paths the UI passes back. */
  private files = new Map<string, File[]>();
  private nextPick = 1;
  private nextFileId = FIRST_FILE_ID;
  private deckTrackId: (number | null)[] = [null, null, null, null];
  private deckToken = [0, 0, 0, 0];
  private tele: T.Telemetry | null = null;
  private fx: string[] | null = null;
  private recordingSince: number | null = null;
  /** One preparation at a time per track, shared by concurrent loads. */
  private preparing = new Map<number, Promise<Float32Array>>();

  private constructor(readonly engine: WebEngine) {
    super();
    engine.onPoll((t, ended) => {
      t.recording = this.recordingSince !== null;
      t.recordedSeconds = this.recordingSince !== null ? (performance.now() - this.recordingSince) / 1000 : 0;
      this.tele = t;
      this.emit("telemetry", t);
      for (const d of ended) this.emit("deck-ended", d);
    });
    engine.ctx.addEventListener("statechange", () => void this.audioStatus().then((s) => this.emit("audio-status", s)));
  }

  /** Starts the backend on a running engine: the real action registry and the kit pads. */
  static async create(engine: WebEngine): Promise<WebAudioBackend> {
    const b = new WebAudioBackend(engine);
    const r = await engine.registry();
    b.registry = r.registry as T.ActionSpec[];
    b.fx = r.fxTypes;
    await Promise.all(b.pads.map((p) => (p.source.type === "kit" ? b.loadKit(p.pad, p.source.id, p) : null)));
    return b;
  }

  /** The demo's simulated engine is replaced by the real one. */
  protected tick() {}

  // ---------------------------------------------------------------- tracks

  /** What to ask the generator for to make this library track. */
  private request(t: DemoTrack): GenerateRequest {
    const sampleRate = this.engine.sampleRate;
    const practice = practiceId(t.row.title);
    if (practice) return { practice, sampleRate };
    return { style: styleForGenre(t.row.genre), bpm: t.row.bpm ?? 124, camelot: t.row.key?.camelot ?? "8A", seed: t.row.id, sampleRate };
  }

  /** Takes the analysis as the track's truth: tempo, key, sections, cues and waveform. */
  private absorb(t: DemoTrack, a: Analysed) {
    this.analysed.set(t.row.id, a);
    const v = a.view;
    t.row.duration = v.duration;
    t.row.bpm = Math.round(v.bpm * 100) / 100;
    t.row.key = v.key;
    t.row.energy = v.energy;
    t.row.lufs = v.lufs;
    t.row.analysis = "done";
    t.firstBeat = v.firstBeat;
    t.period = v.beatPeriod;
    t.sections = v.sections;
    t.cues = v.cues as T.CueDto[];
    this.emit("library-changed", null);
  }

  /** The track's audio at the engine rate, analysing it the first time. */
  private audioFor(t: DemoTrack): Promise<Float32Array> {
    const id = t.row.id;
    const running = this.preparing.get(id);
    if (running) return running.then((a) => a.slice());
    const job = (async () => {
      const file = this.files.get(t.row.path)?.[0];
      if (file) {
        const audio = await this.engine.decode(await file.arrayBuffer());
        if (!this.analysed.has(id)) this.absorb(t, await this.engine.analyse(audio));
        return audio;
      }
      if (this.analysed.has(id)) return this.engine.generate(this.request(t));
      const p = await this.engine.prepare(this.request(t));
      this.absorb(t, { view: p.view, wave: p.wave });
      return p.audio;
    })();
    this.preparing.set(id, job);
    return job.finally(() => this.preparing.delete(id));
  }

  protected detail(t: DemoTrack): T.TrackDetail {
    const a = this.analysed.get(t.row.id);
    if (!a) return super.detail(t);
    const v = a.view;
    return {
      track: t.row,
      analysed: true,
      bpm: v.bpm,
      bpmCandidates: v.bpmCandidates,
      tempoConfidence: v.tempoConfidence,
      driftMs: v.driftMs,
      constantGrid: v.constantGrid,
      gridLocked: v.gridLocked,
      beatsPerBar: v.beatsPerBar,
      firstBeat: v.firstBeat,
      beatPeriod: v.beatPeriod,
      beats: v.beats,
      key: v.key,
      keyConfidence: v.keyConfidence,
      keySecond: v.keySecond,
      tuningCents: v.tuningCents,
      lufs: v.lufs,
      truePeak: v.truePeak,
      autoGainDb: v.autoGainDb,
      energy: v.energy,
      energyCurve: v.energyCurve,
      energyCurveStart: v.energyCurveStart,
      sections: v.sections,
      cues: [...(v.cues as T.CueDto[]), ...this.savedCues(t)],
      audible: v.audible,
    };
  }

  private info(deck: number): T.DeckInfo | null {
    const id = this.deckTrackId[deck];
    if (id == null) return null;
    return { deck, token: this.deckToken[deck], detail: this.detail(this.find(id)), sampleRate: this.engine.sampleRate };
  }

  private changed(deck: number) {
    const info = this.info(deck);
    if (info) this.emit("deck-loaded", info);
  }

  async appInfo(): Promise<T.AppInfo> {
    const info = await super.appInfo();
    return { ...info, version: `${info.version.replace(/-demo$/, "")}-web`, dbPath: "(this browser tab)", fxTypes: this.fx ?? info.fxTypes, decks: [0, 1, 2, 3].map((d) => this.info(d)) };
  }

  async loadTrack(deck: number, trackId: number): Promise<T.DeckInfo> {
    const t = this.find(trackId);
    if (this.tele?.decks[deck]?.playing) throw new Error("This deck is playing. Pause it first, or load onto the other deck.");
    const fresh = !this.analysed.has(trackId);
    const job = (message: string, finished: boolean, error: string | null = null) =>
      this.emit<T.JobProgress>("job", { kind: "analyze", done: finished ? 1 : 0, total: 0, message, finished, error });
    job(fresh ? `Making and analysing "${t.row.title}"` : `Loading "${t.row.title}"`, false);
    let audio: Float32Array;
    try {
      audio = await this.audioFor(t);
    } catch (e) {
      job("", true, `Could not load "${t.row.title}": ${e instanceof Error ? e.message : String(e)}`);
      throw e;
    }
    job(`Loaded "${t.row.title}"`, true);
    const v = this.analysed.get(trackId)!.view;
    const hot = this.savedCues(t).filter((c) => c.role === "hot" && c.slot != null);
    const start = v.cues.find((c) => c.role === "load")?.seconds ?? v.firstBeat;
    const token = await this.engine.load(deck, audio, {
      grid: v.grid,
      key: v.key?.camelot ?? null,
      autoGainDb: this.settings.autoGain ? v.autoGainDb : 0,
      cue: start,
      hotCues: hot.map((c) => ({ slot: c.slot, seconds: c.seconds, loopSeconds: c.loopSeconds, color: c.color })),
    });
    this.deckTrackId[deck] = trackId;
    this.deckToken[deck] = token;
    const info = this.info(deck)!;
    this.emit("deck-loaded", info);
    this.historyData.push({ track_id: t.row.id, played_at: Math.floor(Date.now() / 1000), deck, title: t.row.title, artist: t.row.artist });
    this.emit("history-changed", null);
    return info;
  }

  async trackDetail(id: number) {
    return this.detail(this.find(id));
  }

  async waveform(trackId: number): Promise<T.WaveformData> {
    const a = this.analysed.get(trackId);
    return a && a.wave.length > 8 ? parseWave(a.wave) : super.waveform(trackId);
  }

  // ---------------------------------------------------------------- controls

  async action(id: string, input: T.ActionInput): Promise<void> {
    if (id === "global.record") {
      if (input.type === "press") await (this.recordingSince === null ? this.recordStart() : this.recordStop());
      return;
    }
    if (id.startsWith("app.")) return;
    const m = /^deck\.([A-D])\.(.+)$/.exec(id);
    const deck = m ? m[1].charCodeAt(0) - 65 : -1;
    const sub = m?.[2] ?? "";
    if (sub === "key_sync" || sub.startsWith("grid.")) {
      // These reply (or fail with a reason the person should see).
      const r = (await this.engine.call({ op: "action", id, input })) as GridView | null;
      if (r && "grid" in r) this.applyGrid(deck, r);
      return;
    }
    this.engine.send({ op: "action", id, input });
    if (sub === "eject" && input.type === "press" && !this.tele?.decks[deck]?.playing) this.deckTrackId[deck] = null;
  }

  /** A grid edit on a deck: the track's beats change everywhere it is shown. */
  private applyGrid(deck: number, g: GridView) {
    const id = this.deckTrackId[deck];
    const a = id != null ? this.analysed.get(id) : undefined;
    if (id == null || !a) return;
    a.view = { ...a.view, ...g };
    const t = this.find(id);
    t.row.bpm = Math.round(g.bpm * 100) / 100;
    t.firstBeat = g.firstBeat;
    t.period = g.beatPeriod;
    this.changed(deck);
    this.emit("library-changed", null);
  }

  async seek(deck: number, seconds: number) {
    this.engine.send({ op: "seek", deck, seconds });
  }

  async scratch(deck: number, phase: "start" | "move" | "end", velocity: number) {
    this.engine.send({ op: "scratch", deck, phase, velocity });
  }

  protected deckTrack(deck: number): DemoTrack | null {
    const id = this.deckTrackId[deck];
    return id == null ? null : this.find(id);
  }

  protected deckLoaded(deck: number) {
    this.changed(deck);
  }

  async setGrid(deck: number, edit: T.GridEdit) {
    const g = (await this.engine.call({ op: "gridSet", deck, edit })) as GridView;
    this.applyGrid(deck, g);
  }

  async setHotCue(deck: number, slot: number, seconds: number, loopSeconds?: number | null, color?: number, label?: string) {
    const id = this.deckTrackId[deck];
    if (id == null) return;
    const palette = [0xef4444, 0xf97316, 0xeab308, 0x22c55e, 0x06b6d4, 0x3b82f6, 0x8b5cf6, 0xec4899];
    const c = color ?? palette[slot % 8];
    this.engine.send({ op: "hotCue", deck, slot, seconds, loopSeconds: loopSeconds ?? null, color: c });
    const list = (this.saved.get(id) ?? []).filter((x) => x.slot !== slot);
    list.push({ role: "hot", slot, seconds, loopSeconds: loopSeconds ?? null, label: label ?? "", color: c });
    this.saved.set(id, list);
    this.changed(deck);
  }

  async deleteHotCue(deck: number, slot: number) {
    const id = this.deckTrackId[deck];
    if (id == null) return;
    this.engine.send({ op: "deleteHotCue", deck, slot });
    this.saved.set(id, (this.saved.get(id) ?? []).filter((x) => x.slot !== slot));
    this.changed(deck);
  }

  async setMainCue(deck: number, seconds: number) {
    this.engine.send({ op: "mainCue", deck, seconds });
  }

  async setLoop(deck: number, start: number, end: number, active: boolean) {
    this.engine.send({ op: "loop", deck, start, end, active });
  }

  // ---------------------------------------------------------------- audio and recording

  async devices(): Promise<T.DeviceInfo[]> {
    const sr = this.engine.sampleRate;
    return [{ id: "web:default", name: "This browser's sound output", host: "Web Audio", max_channels: 2, sample_rates: [sr], default_sample_rate: sr, buffer_range: [128, 128], is_default: true }];
  }

  async audioStatus(): Promise<T.AudioStatus> {
    const c = this.engine.ctx;
    const latency = (c.baseLatency || 0) + ((c as AudioContext & { outputLatency?: number }).outputLatency || 0);
    return {
      device: "This browser's sound output",
      isVirtual: false,
      sampleRate: c.sampleRate,
      bufferFrames: 128,
      latencyMs: (latency || 256 / c.sampleRate) * 1000,
      warning: c.state === "running" ? null : "The browser keeps sound off until you click or press a key. Click anywhere to turn it on.",
    };
  }

  async recordStart() {
    if (this.recordingSince !== null) return "";
    this.engine.recordStart();
    this.recordingSince = performance.now();
    return "Recording in the browser. Stop to download the WAV file.";
  }

  async recordStop() {
    if (this.recordingSince === null) return "";
    this.recordingSince = null;
    const chunks = await this.engine.recordStop();
    const d = new Date();
    const pad = (n: number) => String(n).padStart(2, "0");
    const name = `MixIt ${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}.${pad(d.getMinutes())}.wav`;
    download(encodeWav(chunks, this.engine.sampleRate, this.settings.recordFloat), name);
    return `${name}, in your downloads`;
  }

  // ---------------------------------------------------------------- mic

  private micError: string | null = null;
  private micStatus: T.MicStatus | null = null;
  private micRecording = false;

  async studioGet(channel: number | null): Promise<T.StudioDto> {
    return (await this.engine.call(channel === null ? { op: "studioGet" } : { op: "studioGet", channel })) as T.StudioDto;
  }

  async studioSet(channel: number | null, settings: T.StudioDto): Promise<void> {
    this.engine.send(channel === null ? { op: "studioSet", settings } : { op: "studioSet", channel, settings });
  }

  async setScope(source: T.ScopeSource): Promise<void> {
    this.engine.send({ op: "scope", source });
  }

  async inputDevices(): Promise<T.DeviceInfo[]> {
    const sr = this.engine.sampleRate;
    return (await WebEngine.inputDevices()).map((d) => ({ id: d.id, name: d.name, host: "Web Audio", max_channels: 2, sample_rates: [sr], default_sample_rate: sr, buffer_range: null, is_default: d.isDefault }));
  }

  async micState(): Promise<T.MicState> {
    return { status: this.micStatus, error: this.micError, lost: false };
  }

  /** Opens or closes the mic when its settings change (the browser asks the person first). */
  async saveSettings(s: T.Settings) {
    const old = this.settings;
    await super.saveSettings(s);
    const changed = old.micEnabled !== s.micEnabled || old.micDevice !== s.micDevice || old.micVoice !== s.micVoice || (s.micEnabled && !this.engine.micOpenNow);
    if (changed) await this.applyMic(s);
    return s;
  }

  private async applyMic(s: T.Settings) {
    if (!s.micEnabled) {
      this.engine.micClose();
      this.micStatus = null;
      this.micError = null;
      return;
    }
    try {
      const r = await this.engine.micOpen({ device: s.micDevice, voice: s.micVoice ?? true });
      this.micStatus = { device: r.device, sampleRate: r.sampleRate, channels: r.channels, bufferFrames: 128, channel: 0, stereo: r.channels > 1 };
      this.micError = null;
    } catch (e) {
      this.micStatus = null;
      const name = (e as { name?: string }).name;
      this.micError =
        name === "NotAllowedError"
          ? "The browser was not allowed to use the mic. Allow it in the address bar, then turn the mic on again."
          : name === "NotFoundError"
            ? "No microphone was found. Plug one in and try again."
            : String((e as Error).message ?? e);
      throw new Error(this.micError);
    }
  }

  async micRecordStart() {
    if (!this.engine.micOpenNow) throw new Error("Turn the mic on first.");
    if (this.micRecording) return;
    this.micRecording = true;
    this.engine.micRecordStart();
  }

  /** The take becomes a file the sampler and the library can use, like a picked file. */
  async micRecordStop(trim: boolean): Promise<T.MicTake> {
    if (!this.micRecording) throw new Error("Not recording the mic.");
    this.micRecording = false;
    const sr = this.engine.sampleRate;
    let audio = concat(await this.engine.micRecordStop());
    if (trim && audio.length / 2 / sr <= 300) {
      audio = trimSilence(audio, sr);
      if (audio.length === 0) throw new Error("The recording was silent: check the mic gain and meter.");
    }
    const d = new Date();
    const p2 = (n: number) => String(n).padStart(2, "0");
    const name = `Mic ${d.getFullYear()}-${p2(d.getMonth() + 1)}-${p2(d.getDate())} ${p2(d.getHours())}.${p2(d.getMinutes())}.${p2(d.getSeconds())}.wav`;
    const file = new File([encodeWav([audio], sr, true)], name, { type: "audio/wav" });
    const path = `browser:mic/${name}`;
    this.files.set(path, [file]);
    return { path, seconds: audio.length / 2 / sr };
  }

  // ---------------------------------------------------------------- Arrange preview and render

  private rendering = false;
  private renderStop = false;

  /** A clip's track for the renderer: the library track at its path (or with its title). */
  private async renderTrack(n: RenderNeed): Promise<RenderTrack | null> {
    const t = this.tracks.find((x) => x.row.path === n.path) ?? this.tracks.find((x) => x.row.title === n.title);
    if (!t) return null;
    const audio = await this.audioFor(t);
    const v = this.analysed.get(t.row.id)?.view;
    if (!v) return null;
    return { audio, grid: v.grid, autoGainDb: v.autoGainDb ?? 0 };
  }

  /** Renders the passage through the real engine (in the worker), as a WAV file. */
  async previewProject(project: T.MixProject, fromBeat: number, toBeat: number): Promise<ArrayBuffer> {
    const chunks: Float32Array[] = [];
    await this.engine.renderProject({ project, from: fromBeat, to: toBeat, tail: 0.5, autoGain: this.settings.autoGain }, (n) => this.renderTrack(n), (a) => chunks.push(a));
    return encodeWav(chunks, this.engine.sampleRate).arrayBuffer();
  }

  /** Renders the whole mix in the worker and downloads it as a WAV file. Loudness
   * matching needs the whole mix in memory, so it is left to the desktop app here. */
  async renderProject(project: T.MixProject, path: string, _format?: string, targetLufs?: number | null) {
    const name = `${path.replace(/\.(wav|flac|mixit|json)$/i, "") || project.name}.wav`;
    const note = targetLufs != null ? " (loudness matching needs the desktop app, so it is as mixed)" : "";
    this.renderJobs([{ request: { project, autoGain: this.settings.autoGain }, name }], (n) => `${n}, in your downloads${note}`);
  }

  /** Renders each lane as its own WAV file (all the same length) and downloads them. */
  async renderStems(project: T.MixProject) {
    const lanes = [...new Set(project.clips.map((c) => c.lane))].sort();
    if (!lanes.length) throw new Error("The mix has no clips.");
    const base = project.name.replace(/[^\w\- ]+/g, "_").trim() || "Mix";
    this.renderJobs(
      lanes.map((lane) => ({ request: { project, autoGain: this.settings.autoGain, lane }, name: `${base} - Deck ${String.fromCharCode(65 + lane)}.wav` })),
      () => `${lanes.length} stem${lanes.length === 1 ? "" : "s"}, in your downloads`,
    );
  }

  private renderJobs(files: { request: Parameters<WebEngine["renderProject"]>[0]; name: string }[], done: (name: string) => string) {
    if (this.rendering) throw new Error("A mix is already rendering. Stop it first.");
    this.rendering = true;
    this.renderStop = false;
    const sr = this.engine.sampleRate;
    const job = (d: number, total: number, message: string, finished = false, error: string | null = null) => this.emit<T.JobProgress>("job", { kind: "render", done: d, total, message, finished, error });
    job(0, 1, "Rendering your mix…");
    void (async () => {
      try {
        for (const [i, f] of files.entries()) {
          const label = files.length > 1 ? `${f.name}: ` : "";
          // 16-bit parts, folded into Blobs as they pile up so the browser can keep them out of memory.
          const parts: BlobPart[] = [];
          let pending: BlobPart[] = [];
          let samples = 0;
          let last = 0;
          await this.engine.renderProject(
            f.request,
            (n) => {
              job(samples / 2, 0, `${label}Loading “${n.title}”…`);
              return this.renderTrack(n);
            },
            (a, position, total) => {
              pending.push(toPcm16(a));
              samples += a.length;
              if (pending.length >= 30) {
                parts.push(new Blob(pending));
                pending = [];
              }
              const now = performance.now();
              if (now - last > 250) {
                last = now;
                const frac = (i + position / Math.max(1, total)) / files.length;
                job(Math.round(frac * 1000), 1000, `${label}Rendering ${Math.round(frac * 100)} %`);
              }
            },
            () => this.renderStop,
          );
          parts.push(new Blob(pending));
          download(new Blob([wavHeader(samples, sr), ...parts], { type: "audio/wav" }), f.name);
        }
        job(1, 1, done(files[0]?.name ?? ""), true);
      } catch (e) {
        if (e instanceof RenderCancelled) job(0, 1, "Render stopped", true);
        else job(0, 1, "", true, `Could not render the mix: ${e instanceof Error ? e.message : String(e)}`);
      } finally {
        this.rendering = false;
      }
    })();
  }

  async cancelJob() {
    this.renderStop = true;
    await super.cancelJob();
  }

  // ---------------------------------------------------------------- the person's own files

  async pickFolders(): Promise<string[] | null> {
    const files = (await pick({ folder: true, multiple: true })).filter((f) => AUDIO.includes(ext(f.name)));
    if (!files.length) return null;
    const folder = files[0].webkitRelativePath.split("/")[0] || "Picked files";
    const path = `browser:${this.nextPick++}/${folder}`;
    this.files.set(path, files);
    return [path];
  }

  async pickFiles(extensions: string[], _title: string): Promise<string[] | null> {
    const files = await pick({ accept: extensions, multiple: false });
    if (!files.length) return null;
    const path = `browser:${this.nextPick++}/${files[0].name}`;
    this.files.set(path, files);
    return [path];
  }

  async pickSave(defaultName: string) {
    return defaultName;
  }

  /** Adds picked audio files to the library. Returns at once; each file is then decoded
   * and analysed in the browser, reported as a job. */
  async addToLibrary(paths: string[]) {
    const files = paths.flatMap((p) => this.files.get(p) ?? []).filter((f) => AUDIO.includes(ext(f.name)));
    paths.forEach((p) => this.files.delete(p));
    void this.importFiles(files);
  }

  registerFiles(files: File[]): string[] {
    return files.map((f) => {
      const path = `browser:${this.nextPick++}/${f.webkitRelativePath || f.name}`;
      this.files.set(path, [f]);
      return path;
    });
  }

  /** Decodes and analyses one dropped or picked file and adds it to the library. */
  async importTrack(path: string): Promise<T.TrackRow> {
    const f = this.files.get(path)?.[0];
    if (!f) throw new Error("That file is no longer available. Drop it again.");
    const known = this.tracks.find((t) => t.row.path === `browser:/${f.webkitRelativePath || f.name}`);
    if (known) return known.row;
    const job = (message: string, finished: boolean, error: string | null = null) => this.emit<T.JobProgress>("job", { kind: "analyze", done: finished ? 1 : 0, total: 1, message, finished, error });
    job(`Analysing ${f.name}`, false);
    try {
      const t = await this.importOne(f);
      job(`Added ${t.row.title}`, true);
      this.emit("library-changed", null);
      return t.row;
    } catch (e) {
      job("", true, `Could not read ${f.name}`);
      throw e;
    }
  }

  private async importOne(f: File): Promise<DemoTrack> {
    const audio = await this.engine.decode(await f.arrayBuffer());
    const a = await this.engine.analyse(audio);
    const id = this.nextFileId++;
    const path = `browser:/${f.webkitRelativePath || f.name}`;
    this.files.set(path, [f]);
    const t: DemoTrack = {
      row: {
        id,
        path,
        title: stem(f.name),
        artist: "",
        album: f.webkitRelativePath.split("/").slice(-2, -1)[0] ?? "",
        genre: "",
        label: "",
        year: null,
        duration: a.view.duration,
        bpm: null,
        key: null,
        energy: null,
        lufs: null,
        rating: 0,
        color: null,
        playCount: 0,
        lastPlayed: null,
        addedAt: Math.floor(Date.now() / 1000),
        missing: false,
        analysis: "done",
        comment: "",
      },
      sections: [],
      firstBeat: 0,
      period: 0.5,
      wave: new Uint8Array(0),
      cues: [],
    };
    this.tracks.push(t);
    this.absorb(t, a);
    return t;
  }

  private async importFiles(files: File[]) {
    const total = files.length;
    const job = (done: number, message: string, finished = false, error: string | null = null) => this.emit<T.JobProgress>("job", { kind: "analyze", done, total, message, finished, error });
    let failed = 0;
    for (let i = 0; i < files.length; i++) {
      const f = files[i];
      job(i, `Analysing ${i + 1} of ${total}: ${f.name}`);
      try {
        await this.importOne(f);
      } catch {
        failed++;
      }
    }
    const added = total - failed;
    job(total, failed ? `Added ${added} of ${total}; ${failed} could not be read` : `Added ${added} track${added === 1 ? "" : "s"}`, true, total === 0 ? "No audio files in that folder." : null);
  }

  async rescan() {}

  async removeTracks(ids: number[]) {
    for (const id of ids) {
      const t = this.tracks.find((x) => x.row.id === id);
      if (t) this.files.delete(t.row.path);
      this.analysed.delete(id);
    }
    await super.removeTracks(ids);
  }

  async saveProject(path: string, project: T.MixProject) {
    download(new Blob([JSON.stringify(project, null, 1)], { type: "application/json" }), stem(path) + ".mixit");
  }

  async openProject(path: string): Promise<T.MixProject> {
    const f = this.files.get(path)?.[0];
    if (!f) throw new Error("Pick the project file again.");
    return JSON.parse(await f.text()) as T.MixProject;
  }

  // ---------------------------------------------------------------- sampler

  private padSettings(p: T.PadInfo) {
    return { mode: p.mode, gainDb: p.gainDb, pan: p.pan, sync: p.sync, quantized: p.quantized };
  }

  private async loadKit(pad: number, id: string, base?: T.PadInfo): Promise<T.PadInfo> {
    const k = await this.engine.kit(id);
    const info: T.PadInfo = { ...kitPad(pad, id), seconds: k.audio.length / 2 / this.engine.sampleRate, bpm: k.bpm, mode: k.mode };
    if (base) Object.assign(info, { gainDb: base.gainDb, pan: base.pan, sync: base.sync, quantized: base.quantized, mode: base.source.type === "kit" && base.source.id === id ? base.mode : k.mode });
    this.pads[pad] = info;
    await this.engine.loadPad(pad, k.audio, info.bpm, this.padSettings(info));
    return { ...info };
  }

  async samplerLoad(pad: number, source: T.PadSource): Promise<T.PadInfo> {
    const cur = this.pads[pad];
    if (!cur) throw new Error(`no pad ${pad + 1}`);
    const sr = this.engine.sampleRate;
    if (source.type === "kit") {
      if (!DEMO_KIT.some((k) => k.id === source.id)) throw new Error(`no kit sound ${source.id}`);
      return this.loadKit(pad, source.id, { ...cur, source: { type: "empty" } });
    }
    let audio: Float32Array;
    let info: T.PadInfo;
    if (source.type === "file") {
      const f = this.files.get(source.path)?.[0];
      if (!f) throw new Error("Pick the sound again.");
      audio = await this.engine.decode(await f.arrayBuffer());
      info = { ...emptyPad(pad), name: stem(f.name), source, seconds: audio.length / 2 / sr, color: cur.color };
    } else if (source.type === "track") {
      const t = this.find(source.trackId);
      const whole = await this.audioFor(t);
      const a = Math.max(0, Math.round((source.start ?? 0) * sr));
      const b = source.seconds != null ? Math.min(whole.length / 2, a + Math.round(source.seconds * sr)) : whole.length / 2;
      audio = whole.slice(a * 2, b * 2);
      info = { ...emptyPad(pad), name: source.start != null ? `${t.row.title} (loop)` : t.row.title, source, seconds: (b - a) / sr, bpm: t.row.bpm, mode: source.start != null ? 2 : 0, color: cur.color };
    } else {
      return this.samplerClear(pad);
    }
    info.gainDb = cur.gainDb;
    this.pads[pad] = info;
    await this.engine.loadPad(pad, audio, info.bpm, this.padSettings(info));
    return { ...info };
  }

  async samplerClear(pad: number): Promise<T.PadInfo> {
    this.engine.send({ op: "padClear", pad });
    return super.samplerClear(pad);
  }

  async samplerSet(pad: number, patch: T.PadPatch): Promise<T.PadInfo> {
    const p = await super.samplerSet(pad, patch);
    if (p.source.type !== "empty") this.engine.send({ op: "padSettings", pad, settings: this.padSettings(p) });
    return p;
  }

  async samplerReset(): Promise<T.PadInfo[]> {
    const pads = await super.samplerReset();
    return Promise.all(pads.map((p) => (p.source.type === "kit" ? this.loadKit(p.pad, p.source.id) : this.samplerClear(p.pad))));
  }

  async samplerStopAll() {
    this.engine.send({ op: "action", id: "sampler.stop_all", input: { type: "press" } });
  }
}
